"""Rebuild the manually authored, source-reviewed bank. No external enrichment."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
units, questions = [], []
current = None

def unit(pages, title, kind='concept'):
    global current
    if isinstance(pages, int): pages = [pages]
    chapter = 'women' if max(pages) <= 39 else 'population'
    current = dict(id=f'{chapter}-u{sum(u["chapter_id"] == chapter for u in units)+1:03}', chapter_id=chapter,
                   title=title, source_pages=pages, kind=kind, recall_points=[], importance='high', related_unit_ids=[])
    units.append(current)

def q(prompt, answer, category='concept', quick=False, scope='unit', note=''):
    chapter=current['chapter_id']
    obj=dict(id=f'{chapter}-q{sum(x["chapter_id"]==chapter for x in questions)+1:03}', revision=1,
             chapter_id=chapter, unit_ids=[current['id']], source_pages=current['source_pages'], scope=scope,
             format='recall', category=category, importance='high', tags=[current['title']], quick_recall=quick,
             prompt=prompt, expected_answer=dict(style='chain' if '→' in answer else 'bullets',items=answer.split('|')),
             source_note=note)
    questions.append(obj)
    for point in answer.split('|'):
        if point not in current['recall_points']: current['recall_points'].append(point)
    return obj

def b(prompt, answers, category='data', note=''):
    if isinstance(answers,str): answers=[answers]
    for i in range(len(answers)): prompt=prompt.replace('___', '{{b'+str(i+1)+'}}',1)
    obj=q(prompt,'|'.join(answers),category,True,note=note)
    obj['format']='fill_blank'
    obj['blanks']=[dict(id=f'b{i+1}',answer=a,accepted_answers=[],label=f'Blank {i+1}',input_mode='text') for i,a in enumerate(answers)]
    for blank in obj['blanks']:
        try: float(blank['answer'].replace(',',''));blank['input_mode']='decimal'
        except ValueError: pass
    return obj

