q('What contradictions recur across the women chapter?','Formal rights versus weak implementation|Education parity versus employment/leadership gaps|Protection versus limited practical autonomy|Marriage assistance versus dowry reinforcement|Permanent-commission equality versus institutional/social barriers','synthesis',scope='chapter')
unit([40,42,45,46,47,51,52,53,54,57,62,66,67,72],'Population — chapter reconstruction','synthesis')
