unit([15,17,47,49,50,51,57,59,62,66,72],'Population — women, health and dividend','synthesis')
q('Connect women’s empowerment, reproductive health, fertility and the demographic dividend.','Education/employment/autonomy affect fertility choices|Early pregnancy and poor care worsen maternal/infant risks|Counselling, contraception and spacing support choice|Skills + women’s participation → utilise working-age opportunity|Childcare and family care connect fertility concerns with employment','synthesis',scope='chapter')
q('Why can a favourable age structure still produce social unrest rather than a dividend?','Working-age opportunity without skills, human capital and jobs → frustrated/unemployed youth → unrest|Arab Spring example|Education, vocational skills, entrepreneurship and female participation are enabling conditions','synthesis',scope='chapter')
unit([60,61,62,63,64,65,66,71,72],'Population — policy evolution and models','synthesis')
